/* YouTube DNA — play red on white, thumbnail-first */
.theme-youtube-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.982 0 0);
  --surface-2: oklch(0.961 0 0);
  --fg: oklch(0.168 0 0);
  --fg-muted: oklch(0.489 0 0);
  --accent: oklch(0.628 0.258 29.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.277 0 0);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.75rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Roboto Condensed", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.03em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-youtube-dna h1,
.theme-youtube-dna h2,
.theme-youtube-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-youtube-dna { --font-ui: var(--font-display); }
.theme-youtube-dna h1, .theme-youtube-dna h2 { text-transform: uppercase; font-weight: 700; }
.theme-youtube-dna button { font-weight: 600; }

/* depth */
.theme-youtube-dna button { border-radius: var(--radius-pill); }
.theme-youtube-dna button:active { transform: scale(0.97); }
.theme-youtube-dna input, .theme-youtube-dna select { border-radius: var(--radius-pill); }
.theme-youtube-dna input:focus-visible, .theme-youtube-dna select:focus-visible, .theme-youtube-dna textarea:focus-visible { outline: none; border-color: oklch(0.520 0.150 255.0); box-shadow: 0 0 0 1px oklch(0.520 0.150 255.0); }
.theme-youtube-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-youtube-dna tbody td { border-bottom: 1px solid var(--line); }
.theme-youtube-dna tbody tr:hover td { background: var(--surface-2); }
.theme-youtube-dna a { color: oklch(0.480 0.170 255.0); text-decoration: none; }
.theme-youtube-dna a:hover { text-decoration: underline; text-underline-offset: 3px; }
.theme-youtube-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-youtube-dna h2 { padding-bottom: 0.3rem; background: linear-gradient(90deg, var(--accent) 0 3.5rem, var(--line) 3.5rem) bottom left / 100% 3px no-repeat; }
.theme-youtube-dna kbd { font-family: var(--font-mono); font-size: 0.78em; padding: 0.1em 0.5em; border-radius: var(--radius-sm); background: var(--surface-2); border: 1px solid var(--line); box-shadow: 0 1px 0 var(--line); }
.theme-youtube-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-youtube-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-youtube-dna ::-webkit-scrollbar-thumb { background: oklch(0.75 0 0); border-radius: 999px; }
.theme-youtube-dna .label-caps { font-family: var(--font-display); color: var(--fg); background: var(--surface-2); border-radius: var(--radius-pill); padding: 0.15em 0.7em; }
.theme-youtube-dna .themed-border { border-color: var(--line); }

/* alt mode: dark theme — true #0f0f0f player chrome */
.theme-youtube-dna.alt-mode {
  --bg: oklch(0.130 0.000 0.0);
  --surface: oklch(0.190 0.000 0.0);
  --surface-2: oklch(0.245 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.72 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-youtube-dna.alt-mode a { color: oklch(0.750 0.120 250.0); }
.theme-youtube-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.45 0 0); }
.theme-youtube-dna.alt-mode input:focus-visible, .theme-youtube-dna.alt-mode select:focus-visible, .theme-youtube-dna.alt-mode textarea:focus-visible { border-color: oklch(0.750 0.120 250.0); box-shadow: 0 0 0 1px oklch(0.750 0.120 250.0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
